from taf.sw.dcap.rd.services.cm.cm_base import CM
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.start_trace_body_v1 import StartTraceBodyV1
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CMv1(CM):

    def create_bts(self, host, port, username, password, bts_alias, timeout):
        self._create_bts = self.api_client.create_bts_v1(
            bts_login_with_optional_credentials={'alias': bts_alias, 'host': host, 'port': port,
                                                 'username': username, 'password': password}, _request_timeout=timeout)
        return self._create_bts

    def create_multiple_bts(self, bts_info, timeout):
        create_multiple_bts = []
        for bts in bts_info:
            _create_multiple_bts = self.api_client.create_multiple_bts_v1(
                bts_login_with_optional_credentials={'alias': bts['alias'], 'host': bts['host'],
                                                     'port': bts['port'],
                                                     'username': bts['username'],
                                                     'password': bts['password']}, _request_timeout=timeout)
            create_multiple_bts.append(_create_multiple_bts)
        return create_multiple_bts

    def start_trace_from(self, bts, custom_filter_file=None, force=None, tag=None, trace_profiles=None,
                         duration=None, wait_for_activation=False, timeout=400):
        start_trace_body = StartTraceBodyV1(custom_filter_file=custom_filter_file, force=force, tag=tag, bts=bts,
                                            trace_profiles=trace_profiles, duration=duration)
        self._start_trace_body = self.api_client.new_trace_v1(start_trace_body_v1=start_trace_body)
        return self.wait_for_start_trace_activation(wait_for_activation=wait_for_activation, timeout=timeout)

    def start_trace(self, bts, tag, duration, force, gnb_trace_profile, enb_trace_profile,
                    custom_filter_file,
                    gnb_custom_profile, enb_custom_profile, wait_for_activation, control_plane_interface, timeout):
        trace_profiles = self.start_trace_profile_selection(gnb_trace_profile=gnb_trace_profile,
                                                            enb_trace_profile=enb_trace_profile,
                                                            gnb_custom_profile=gnb_custom_profile,
                                                            enb_custom_profile=enb_custom_profile,
                                                            control_plane_interface=control_plane_interface,
                                                            timeout=timeout)
        return self.start_trace_from(custom_filter_file=custom_filter_file, force=force, tag=tag, bts=bts,
                                     trace_profiles=trace_profiles, duration=duration,
                                     wait_for_activation=wait_for_activation, timeout=timeout)

    def get_all_bts_info(self, timeout):
        return self.api_client.get_all_bts_v1(_request_timeout=timeout)

    def get_bts_by_id(self, bts_id, timeout):
        bts_id = self._get_bts_id(bts_id=bts_id)
        return self.api_client.get_bts_by_id_v1(bts_id=bts_id, _request_timeout=timeout)

    def get_trace_info_by_id(self, trace_id, timeout):
        trace_id = self._get_trace_id(trace_id)
        return self.api_client.get_trace_info_by_id_v1(trace_id=trace_id, _request_timeout=timeout)

    def get_all_trace_info(self, timeout):
        return self.api_client.get_all_trace_info_v1(_request_timeout=timeout)

    def get_5g_profiles(self, timeout):
        return self.api_client.get_profiles5_gv1(_request_timeout=timeout)

    def get_lte_profiles(self, timeout):
        return self.api_client.get_profiles4_gv1(_request_timeout=timeout)
